public class ResourcePrefixDetector extends ResourceXmlDetector {
    private static final String PREFIX = "resourcePrefix";

    @Override
    public boolean appliesTo(Context context, File file) {
        return context.getProject().getResourcePrefix() != null;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (context.getResourceFolderType() == ResourceFolderType.VALUES) {
            if (element.getParentNode() instanceof Element
                    && element.getParentNode().getNodeName().equals(TAG_RESOURCES)) {
                Attr name = element.getAttributeNode(ATTR_NAME);
                if (name != null) {
                    checkResourceName(context, name.getValue(), context.getValueLocation(name));
                }
            }
        }
    }

    @Override
    public void visitDocument(XmlContext context, Document document) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType != null && folderType != ResourceFolderType.VALUES) {
            String fileName = context.file.getName();
            int index = fileName.indexOf('.');
            if (index != -1) {
                fileName = fileName.substring(0, index);
            }
            checkResourceName(context, fileName, Location.create(context.file));
        }
    }

    private void checkResourceName(XmlContext context, String name, Location location) {
        String prefix = context.getProject().getResourcePrefix();
        if (prefix != null && !name.startsWith(prefix)) {
            context.report(ISSUE, location,
                String.format("Expected resource name to start with '%1$s'", prefix));
        }
    }

    public static final Issue ISSUE = Issue.create(
        "ResourceName",
        "Resource with Wrong Prefix",
        "In Gradle projects you can specify a resource prefix...",
        Category.CORRECTNESS, 5, Severity.WARNING,
        new Implementation(ResourcePrefixDetector.class, Scope.RESOURCE_FILE_SCOPE));
}
```

