public class ResourcePrefixDetector extends ResourceXmlDetector {
    private static final String TAG_RESOURCES = "resources";
    private static final String ATTR_NAME = "name";

    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "In Gradle projects you can specify a resource prefix (resourcePrefix) that all resources in the project must conform to. This makes it easier to ensure that you do not accidentally combine resources from different libraries, since they all end up in the same shared app namespace.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(ResourcePrefixDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(@NonNull Context context, @NonNull File file) {
        String prefix = context.getProject().getResourcePrefix();
        return prefix != null && !prefix.isEmpty();
    }

    @Nullable
    @Override
    public Collection<String> getApplicableElements() {
        return XmlScanner.ALL;
    }

    @Override
    public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == null || folderType == ResourceFolderType.VALUES) {
            return;
        }

        String fileName = context.file.getName();
        int dot = fileName.indexOf('.');
        if (dot != -1) {
            fileName = fileName.substring(0, dot);
        }

        checkResourceName(context, fileName, Location.create(context.file));
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (context.getResourceFolderType() != ResourceFolderType.VALUES) {
            return;
        }

        Node parent = element.getParentNode();
        if (!(parent instanceof Element) || !TAG_RESOURCES.equals(parent.getNodeName())) {
            return;
        }

        Attr nameAttr = element.getAttributeNode(ATTR_NAME);
        if (nameAttr == null) {
            return;
        }

        String name = nameAttr.getValue();
        if (name != null) {
            checkResourceName(context, name, context.getValueLocation(nameAttr));
        }
    }

    private void checkResourceName(@NonNull XmlContext context, @NonNull String name, @NonNull Location location) {
        String prefix = context.getProject().getResourcePrefix();
        if (prefix != null && !name.startsWith(prefix)) {
            context.report(ISSUE, location,
                    String.format("Expected resource to start with prefix '%1$s'", prefix));
        }
    }
}
